def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings."""
    # Find first difference
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            # Check if this is a replacement
            if len(s_in) == len(s_out):
                return (s_in[i], s_out[i], i)
            elif len(s_in) > len(s_out):
                # Deletion
                return (s_in[i], '', i)
            else:
                # Insertion
                return ('', s_out[i], i)

    # If we reach here, one string is prefix of other
    if len(s_in) > len(s_out):
        return (s_in[-1], '', len(s_in)-1)
    elif len(s_in) < len(s_out):
        return ('', s_out[-1], len(s_in))
    return None

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a change."""
    # Simple approach: find minimal edit and create rules for it
    edit = find_minimal_edit(s_in, s_out)
    if edit:
        old_sub, new_sub, pos = edit
        # Return most specific rule first
        if old_sub and new_sub:
            return [(old_sub, new_sub)]
        elif old_sub and not new_sub:
            return [(old_sub, '')]  # deletion
        elif not old_sub and new_sub:
            return [('', new_sub)]  # insertion
    return []

# Now let's work with our data
