outputs = ['dz', 'jbwgix', 'jacghac', 'ugfbh', 'fx']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:", changed)

# Process each changed pair
rules = []
for idx, s_in, s_out in changed:
    print(f"\nProcessing pair {idx}: {s_in} -> {s_out}")

    # Find minimal edit
    edit = find_minimal_edit(s_in, s_out)
    print(f"Minimal edit: {edit}")

    if edit:
        old_sub, new_sub, pos = edit
        print(f"Replace '{old_sub}' with '{new_sub}' at position {pos}")

        # For now, let's just try the basic replacement
        if old_sub and new_sub:
            rules.append((old_sub, new_sub))

